SELECT a.View, a.Status AS AngleStatus, a.InputArtifactId AS AngleInput, a.OutputArtifactId AS AngleOutput, at.AttemptNumber, at.Status AS AttemptStatus, at.InputArtifactId AS AttemptInput, at.OutputArtifactId AS AttemptOutput, src.Kind AS SourceKind, outp.Kind AS OutputKind, outp.SourceImageId AS OutputSource FROM CharacterIdentityAngles a LEFT JOIN CharacterIdentityAngleAttempts at ON at.AngleId = a.Id LEFT JOIN SceneAssetImages src ON src.Id = at.InputArtifactId LEFT JOIN SceneAssetImages outp ON outp.Id = at.OutputArtifactId WHERE a.BuildId = '49c3175356874e908b181cad815f7141' ORDER BY a.View, at.AttemptNumber;
